"""Reference-led academic presentation; facts sourced in docs/CONTENT_REVIEW.md."""
from pathlib import Path

def apply(pages, link, thesis_title):
    portrait = Path(__file__).resolve().parents[1] / 'assets/portrait.jpg'
    photo = '<img src="/assets/portrait.jpg" alt="Xin Yu" width="192" height="192" fetchpriority="high">' if portrait.exists() else '<span class="portrait-pending" role="img" aria-label="Portrait of Xin Yu pending original image file">XY<span>Portrait pending</span></span>'
    pipeline = '<ol class="mini-pipeline" aria-label="Offline visual negative construction pipeline">' + ''.join(f'<li><span class="step-number">0{i}</span><strong>{title}</strong><small>{model}</small></li>' for i,(title,model) in enumerate([('Self-rollout','Qwen2.5-VL-3B'),('Judge & extract','Qwen3-8B'),('Synthesize','Qwen-Image'),('Filter & verify','Preference pairs'),('Cross-modal DPO','Model training')],1)) + '</ol>'
    def card(category,title,description,tags,action='Research project',url=None):
        action = link(url,action) if url else f'<span class="card-status">{action}</span>'
        return f'<article class="research-card"><p class="eyebrow">{category}</p><h3>{title}</h3><p>{description}</p><div class="card-footer"><span>{tags}</span>{action}</div></article>'
    thesis_card=card('Research · Multimodal alignment',thesis_title,'Built an offline preference-data pipeline using model rollouts, language-model judging, and image generation. MMHal-Bench improved from 3.82 to 3.99; hallucination rate fell from 37.6% to 33.3%. Benchmark trade-offs and evaluation settings are documented on the project page.','Qwen2.5-VL · DPO · Data curation','Read project','/research/thesis/')
    vqa=card('Research · Trustworthy AI','Mitigating Visual Hallucination in VQA for MLLMs','Constructed positive and negative training pairs with region masking and caption-based supervision. Reduced the dataset from 265K to 163K examples without accuracy loss, as reported in the CV.','Vision-language models · VQA')
    selection=card('Research · Data selection','Data Selection for GRPO-based MLLM Training','Developed advantage-based filtering to assess training-data utility, identifying roughly 50% of examples as ineffective and a high-value subset of approximately 5%. Built a vectorized Parquet pipeline for reproducible selection.','GRPO · Parquet · Data utility')
    curriculum=card('Research · Training strategy','Curriculum Learning for Multimodal Models','Evaluated 20 SFT checkpoints and constructed a 72K-example reasoning curriculum ranked by Pass@5 difficulty. Explored Naive GRPO and CoT Rollout GRPO with hint fading; early experiments indicated faster convergence.','Curriculum learning · GRPO')
    macronet=card('Research software · PyTorch','MacroNet: Composable Neural Network Programming','Contributed implementation, model experiments, and technical documentation for a composable framework, including compact MLP and LeNet architecture examples. Work with Prof. Min Li’s group.','PyTorch · Model implementation','View GitHub','https://github.com/sumowi/MacroNet')
    verification=card('Research · Multimodal verification','Verifying Software Acceptance Reports','Led a training-free four-stage framework with Prof. Lei Wang’s group / Hunan Jiace Test. Used MiniCPM-V to summarize visual and textual evidence and Qwen2-7B for consistency reasoning. The university–industry system is now in use in a factory.','MiniCPM-V · Qwen2 · Verification')
    publication='''<article class="publication" id="resynth"><div class="publication-top"><p class="eyebrow">CSU-JPG Lab · Manuscript</p><span class="badge">Under review · ICLR 2027</span></div><h2>ReSynth: Verified Synthetic Data for Multi-Image Understanding</h2><p>Developed a relation-based synthetic-data pipeline with visual verification across five multi-image reasoning abilities. Trained Qwen2.5-VL-7B with GRPO on a 13K-example synthetic corpus.</p><div class="metrics"><div><strong>13K</strong><span>Synthetic examples</span></div><div><strong>+4.25</strong><span>Average accuracy points</span></div><div><strong>+9.75</strong><span>Counting accuracy points</span></div></div><p class="small">The average gain covers BLINK, MUIRBench, and VLM2-Bench; the counting gain is attributed to visual verification. Submission under review; not an accepted publication. Public manuscript and author list pending.</p><div class="card-footer"><span>Multimodal reasoning · Synthetic data · GRPO</span><span class="card-status">Paper details forthcoming</span></div></article>'''
    featured=f'''<article class="thesis-highlight"><div><span class="badge">Featured thesis · 2026</span><h3>{thesis_title}</h3><p>Constructing visual negatives aligned with a model’s own hallucinations for cross-modal preference training.</p>{link('/research/thesis/','Methodology, results & limitations')}<div class="compact-stats"><span><strong>15,732</strong>Source samples</span><span><strong>≈7.5K</strong>Training pairs</span><span><strong>3.82 → 3.99</strong>MMHal-Bench</span></div></div><div>{pipeline}<p class="small">An offline construction pipeline; arrows indicate processing order.</p></div></article>'''
    def appointment(institution, institution_url, role, dates, description, logo='csu.png', group=None, group_url=None, advisor=None, advisor_url=None):
        icon_url = group_url if logo == 'csu-jpg.png' else institution_url
        icon_label = group if logo == 'csu-jpg.png' else institution
        group_link = f' <span class="institution-divider">·</span> <a class="group-link" href="{group_url}">{group}</a>' if group else ''
        advisor_link = f' <span class="institution-divider">·</span> Advisor <a href="{advisor_url}">{advisor}</a>' if advisor else ''
        return f'<article class="appointment"><a class="institution-icon" href="{icon_url}" aria-label="{icon_label}"><img src="/assets/institutions/{logo}" alt="" width="48" height="48" loading="lazy"></a><div class="appointment-content"><div class="appointment-topline"><h3><a class="institution-name" href="{institution_url}">{institution}</a>{group_link}</h3><span class="appointment-date">{dates}</span></div><p class="appointment-position">{role}{advisor_link}</p><p class="appointment-description">{description}</p></div></article>'
    research_experience = '<section class="section experience-section"><div class="experience-section-label"><p class="eyebrow">Research</p><h2>Research experience</h2></div><div class="appointments">' + appointment('Central South University','https://www.csu.edu.cn/','Research Assistant','Apr 2025–present','Multimodal hallucination, preference optimization, synthetic data, and training strategies.',logo='csu-jpg.png',group='CSU-JPG Group',group_url='https://github.com/CSU-JPG',advisor='Jinpeng Wang',advisor_url='https://fingerrec.github.io/') + appointment('Central South University','https://www.csu.edu.cn/','Research Assistant','Apr 2025–present','Composable neural network software, implementation, and model experiments.',group='Prof. Min Li’s Group',group_url='https://faculty.csu.edu.cn/limin1/en',advisor='Min Li',advisor_url='https://faculty.csu.edu.cn/limin1/en') + appointment('Central South University','https://www.csu.edu.cn/','Research Assistant & Project Lead','Jun 2024–Mar 2025','University–industry collaboration with Hunan Jiace Test on multimodal verification for software acceptance reports; the system is now in use in a factory.',group='Prof. Lei Wang’s Group',group_url='https://faculty.csu.edu.cn/leiwang/en/index.htm',advisor='Lei Wang',advisor_url='https://faculty.csu.edu.cn/leiwang/en/index.htm') + '</div></section>'
    internships = '<section class="section experience-section"><div class="experience-section-label"><p class="eyebrow">Industry</p><h2>Internships</h2>' + link('/experience/','Experience & projects') + '</div><div class="appointments">' + appointment('BROAD Group','https://en.broad.com/','AI Developer Intern','Jan–Mar 2025','Curated 50K user texts into 3K dialogues; fine-tuned Qwen2.5-7B and built an AI-VTuber streaming system.',logo='briefcase.svg') + appointment('Hunan Jiace Test (JCISE)','https://m.zhipin.com/companys/1ee052f84cfdf4d31nR_2di6GVU~.html','Technical Development Intern','Sep 2024–Mar 2025','Developed 15 REST APIs with reported average latency below 0.5 seconds, alongside multimodal model development.',logo='briefcase.svg') + '</div></section>'
    bio = '''<p>I am currently an M.S. student in Artificial Intelligence at <a href="https://www.columbia.edu/">Columbia University</a>. I received my B.S. in Computer Science and Technology with <strong>First-Class Honours</strong> from <a href="https://www.csu.edu.cn/">Central South University</a>.</p><p>At Central South University, I work with <a href="https://fingerrec.github.io/">Prof. Jinpeng Wang</a> in the <a href="https://github.com/CSU-JPG">CSU-JPG Group</a>. I have also collaborated with <a href="https://faculty.csu.edu.cn/leiwang/en/index.htm">Prof. Lei Wang</a> and <a href="https://faculty.csu.edu.cn/limin1/en">Prof. Min Li</a>. In Prof. Lei Wang’s group, I worked on a university–industry collaboration with Hunan Jiace Test to develop a multimodal verification system for software acceptance reports. The system is now in use in a factory.</p><p>My research interests include <strong>vision-language models</strong>, <strong>data-centric AI</strong>, and <strong>reinforcement learning</strong>. My recent work focuses on multimodal reasoning, visual hallucination, preference optimization, and verified synthetic data for more reliable multimodal systems.</p>'''
    home=f'''<section class="landing-hero"><div class="landing-intro"><p class="eyebrow">AI research · Multimodal learning · Columbia University</p><h1>Building AI<br>that <em>reasons.</em></h1><p class="landing-description">I’m <strong>Xin Yu</strong>, an M.S. student in Artificial Intelligence at Columbia University. My research spans vision-language models, data-centric AI, and reinforcement learning, with a focus on reliable multimodal reasoning.</p><div class="actions">{link('/research/','Explore my research','button')}{link('https://github.com/yuxin0923','GitHub')}{link('mailto:xy2765@columbia.edu','Get in touch')}</div></div><aside class="landing-profile"><div class="portrait">{photo}</div><p>Xin Yu<span>Multimodal reasoning & trustworthy AI</span></p></aside></section><section class="education-band" aria-label="Education and research focus"><div><div class="education-summary"><div class="education-entry"><a class="education-emblem" href="https://www.columbia.edu/" aria-label="Columbia University website"><img class="columbia-emblem" src="/assets/institutions/columbia.svg" alt="Columbia University emblem" width="40" height="40"></a><div><a class="education-school" href="https://www.columbia.edu/">Columbia University</a><p>M.S. Artificial Intelligence<span>Sep 2026–Dec 2027 · Expected completion</span></p></div></div><div class="education-entry"><a class="education-emblem" href="https://www.csu.edu.cn/" aria-label="Central South University website"><img src="/assets/institutions/csu.png" alt="Central South University emblem" width="40" height="40"></a><div><a class="education-school" href="https://www.csu.edu.cn/">Central South University</a><p>B.S. Computer Science and Technology<span>2022–2026 · First-Class Honours</span></p></div></div></div></div><div class="focus-summary"><p class="eyebrow">Research focus</p><p>Vision-language models<br>Data-centric AI<br>Reinforcement learning</p><span>Based in New York, NY</span></div></section><section class="section"><div class="section-heading"><h2><span class="section-number">01 /</span> Research highlights</h2>{link('/research/','All research')}</div>{featured}</section><section class="section"><div class="section-heading"><h2><span class="section-number">02 /</span> Manuscript</h2>{link('/publications/','Publications')}</div>{publication}</section><section class="section"><div class="section-heading"><h2><span class="section-number">03 /</span> Selected work</h2>{link('/experience/','Experience & projects')}</div><div class="research-grid">{vqa}{macronet}</div></section><section class="contact-strip"><div><p class="eyebrow">Connect</p><h2>Interested in reliable multimodal AI?</h2><p>I welcome research conversations and collaboration opportunities.</p></div>{link('mailto:xy2765@columbia.edu','xy2765@columbia.edu')}</section>'''
    home=home.replace('<section class="section"><div class="section-heading"><h2><span class="section-number">01 /</span>', '<section class="section about-introduction"><h2>About me</h2><div class="bio-copy">' + bio + '</div></section><section class="section"><div class="section-heading"><h2><span class="section-number">01 /</span>',1)
    home=home.replace('<section class="contact-strip">', internships + '<section class="contact-strip">')
    pages['/']=(pages['/'][0],pages['/'][1],home)
    pages['/research/']=('Research — Xin Yu','Multimodal reasoning, hallucination mitigation, preference optimization, and data-centric model training.',f'''<header class="page-intro"><p class="eyebrow">Research</p><h1>Reliable models.<br><em>Better training signals.</em></h1><p class="lead">I explore how visual evidence, preference data, and training strategies shape the reliability of multimodal models.</p></header>{publication}<section class="section"><div class="section-heading"><h2>Research projects</h2><span class="small">Methods, experiments & research software</span></div><div class="research-grid">{thesis_card}{vqa}{selection}{curriculum}{macronet}{verification}</div></section>{research_experience}{internships}''')
    pages['/publications/']=('Publications — Xin Yu','Manuscripts and publication status for Xin Yu.',f'<header class="page-intro"><p class="eyebrow">Publications</p><h1>Manuscripts & publications</h1><p class="lead">Current submission status and research context.</p></header>{publication}<section class="section"><h2>Undergraduate Honours Thesis</h2><h3>{thesis_title}</h3><p>2026 · Supervisor: Yang Gao · DI40001 DIICSU Honours Project</p>{link("/research/thesis/","Read the project summary")}</section>')
    title,desc,body=pages['/experience/']
    body=body.replace('<h3>Hunan Jiace Test</h3>', '<h3 id="jiace">Hunan Jiace Test</h3>')
    body=body.replace('<section class="section"><h2>Experience</h2>', '<section class="section"><h2>Experience</h2>')
    # Add matching institutional rows while retaining all detailed project descriptions.
    body=body.replace('<section class="section"><h2>Experience</h2>', internships + '<section class="section"><h2>Experience in detail</h2>',1)
    pages['/experience/']=(title,desc,body)
    title,desc,body=pages['/about/']
    education_start=body.index('<section class="section"><p class="eyebrow">Education</p>')
    body='<header class="page-intro"><p class="eyebrow">About Xin Yu</p><h1>About me</h1></header><section class="section about-introduction"><h2>Background & research</h2><div class="bio-copy">' + bio + '</div></section>' + body[education_start:]
    body=body.replace('<h2>Tools for experimentation.</h2>','<h2>Research & engineering skills</h2>')
    body += '<section class="section" id="cv"><p class="eyebrow">Curriculum vitae</p><h2>Academic background</h2><p>The education, research, and experience on this site are summarized from my CV. A downloadable public version is being prepared.</p><p>For a current copy, contact <a href="mailto:xy2765@columbia.edu">xy2765@columbia.edu</a>.</p></section>'
    pages['/about/']=(title,desc,body)
    return pages
